const { Client, Intents, Collection } = require('discord.js');
const { token } = require('./config.json');
const fs = require('fs');
const { ban } = require('./commands/ban');

const client = new Client({ intents: [Intents.FLAGS.GUILDS, Intents.FLAGS.GUILD_MESSAGES] });

client.commands = new Collection();
const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
  const command = require(`./commands/${file}`);
  client.commands.set(command.data.name, command);
}

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = client.commands.get(interaction.commandName);

  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

client.login(token);
```

This code creates a Discord bot using Discord.js v14. The bot has one command, ban, which is a slash command. The bot listens for interactionCreate events and executes the corresponding command if it is a slash command. The code also includes a collection of commands and a configuration file for the bot's token.

function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    let num = arr[i];
    if (num > 1) {
      for (let j = 2; j <= Math.sqrt(num); j++) {
        if (num % j == 0) {
          console.log(num + " is not a prime number");
          return;
        }
      }
      console.log(num + " is a prime number");
    }
  }
}

// Example usage
let arr = [2, 3, 5, 7, 11];
checkPrime(arr);
```

In this function, we first loop through each number in the array. If the number is greater than 1, we then loop through all numbers from 2 to the square root of the number. If the number is divisible by any of these numbers, we print that it is not a prime number and return from the function. If the number is not divisible by any of these numbers, we print that it is a prime number.

